theorem amplitudeDamping_step_completely_positive (gamma : ℝ) (h : ℝ) {m : ℕ}
{rho' : Matrix (Fin m × Fin 2) (Fin m × Fin 2) ℂ}
(hρ' : PositiveSemidefinite rho') :
PositiveSemidefinite
(krausMapExt (eulerLindbladStep 0 (amplitudeDampingL gamma) h) rho')

theorem dephasing_step_completely_positive (gamma : ℝ) (h : ℝ) {m : ℕ}
{rho' : Matrix (Fin m × Fin 2) (Fin m × Fin 2) ℂ}
(hρ' : PositiveSemidefinite rho') :
PositiveSemidefinite (krausMapExt (eulerLindbladStep 0 (dephasingL gamma) h) rho')

protected theorem PositiveSemidefinite.add {A B : Matrix ι ι ℂ}
(hA : PositiveSemidefinite A) (hB : PositiveSemidefinite B) :
PositiveSemidefinite (A + B)

theorem PositiveSemidefinite.mul_mul_conjTranspose {A : Matrix ι ι ℂ}
(hA : PositiveSemidefinite A) {κ : Type*} [Fintype κ] (B : Matrix κ ι ℂ) :
PositiveSemidefinite (B * A * Bᴴ)

theorem PositiveSemidefinite.sum {δ : Type*} {s : Finset δ} {f : δ → Matrix ι ι ℂ}
(h : ∀ i ∈ s, PositiveSemidefinite (f i)) :
PositiveSemidefinite (∑ i ∈ s, f i)

theorem krausMapExt_product_state {n : ℕ} (K : Fin n → Matrix ι ι ℂ) {m : ℕ}
(A : Matrix (Fin m) (Fin m) ℂ) (ρ : Matrix ι ι ℂ) :
krausMapExt K (A ⊗ₖ ρ) = A ⊗ₖ krausMap K ρ

theorem krausMap_completely_positive {n : ℕ} (K : Fin n → Matrix ι ι ℂ) {m : ℕ}
{ρ' : Matrix (Fin m × ι) (Fin m × ι) ℂ} (hρ' : PositiveSemidefinite ρ') :
PositiveSemidefinite (krausMapExt K ρ')

theorem hasConcreteNSRefutation_iff_gauge {n : Nat}
(g : Fin n → Bool) (F : Formula n) (d : Nat) :
HasConcreteNSRefutation (flipFormula g F) d ↔ HasConcreteNSRefutation F d

theorem min_concrete_ns_degree_gauge_invariant {n : Nat}
(g : Fin n → Bool) (F : Formula n) (d : Nat) :
IsMinConcreteNSDegree (flipFormula g F) d ↔ IsMinConcreteNSDegree F d

theorem contraFormula_unsatisfiable_of_certificate {d : Nat}
(cert : ConcreteRatAlgebraicNSRefutation contraFormula d) :
FormulaUnsatisfiable contraFormula

theorem eval_concrete_int_refutation {n : Nat} {F : Formula n} {d : Nat}
(cert : ConcreteIntAlgebraicNSRefutation F d) (x : Fin n → Int) :
evalPoly (certificatePoly 0 1 (-1) cert.q F cert.r) x = 1

theorem eval_concrete_rat_refutation {n : Nat} {F : Formula n} {d : Nat}
(cert : ConcreteRatAlgebraicNSRefutation F d) (x : Fin n → Rat) :
evalPoly (certificatePoly (Rat.ofInt 0) (Rat.ofInt 1) (Rat.ofInt (-1)) cert.q F cert.r) x = 1

theorem int_cert_evaluates_to_one {n : Nat} {F : Formula n} {d : Nat}
(cert : ConcreteIntAlgebraicNSRefutation F d) (x : Fin n → Int) :
evalPoly (certificatePoly 0 1 (-1) cert.q F cert.r) x = 1

theorem int_refutation_soundness {n : Nat} {F : Formula n} {d : Nat}
(cert : ConcreteIntAlgebraicNSRefutation F d) :
FormulaUnsatisfiable F

theorem rat_cert_evaluates_to_one {n : Nat} {F : Formula n} {d : Nat}
(cert : ConcreteRatAlgebraicNSRefutation F d) (x : Fin n → Rat) :
evalPoly (certificatePoly (Rat.ofInt 0) (Rat.ofInt 1) (Rat.ofInt (-1)) cert.q F cert.r) x = 1

theorem rat_refutation_soundness {n : Nat} {F : Formula n} {d : Nat}
(cert : ConcreteRatAlgebraicNSRefutation F d) :
FormulaUnsatisfiable F
